// Account-scoped persistence and translation; called only after session verification.
const apiStatuses=new Set(['draft','notified','in_progress','verification','closed']);
function apiJson(value,status=200,extra={}){return new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store, private','X-Content-Type-Options':'nosniff',...extra}});}
