const apiText=(x,max=12000)=>typeof x==='string'?x.slice(0,max):'';
function apiDict(x){if(!x||typeof x!=='object'||Array.isArray(x))return {};const out={};for(const [k,v]of Object.entries(x)){if(!/^[a-zA-Z][\w]{0,60}$/.test(k)||['__proto__','constructor','prototype'].includes(k))continue;if(typeof v==='string')out[k]=v.slice(0,16000);else if(typeof v==='boolean')out[k]=v;else if(Array.isArray(v))out[k]=v.filter(i=>typeof i==='string').slice(0,50).map(i=>i.slice(0,1000));}return out;}
function apiPayload(x){if(!x||typeof x!=='object'||Array.isArray(x))throw new Error('invalid');const out={common:apiDict(x.common),mail:apiDict(x.mail),report:apiDict(x.report),files:Array.isArray(x.files)?x.files.filter(n=>typeof n==='string').slice(0,30).map(n=>n.slice(0,250)):[],drafts:{},checks:apiDict(x.checks),translationSource:apiText(x.translationSource,30000),sampleModes:{mail:x.sampleModes?.mail===true,report:x.sampleModes?.report===true}};for(const mode of ['mail','report'])if(x.drafts?.[mode]){const r=x.drafts[mode];out.drafts[mode]={subject:apiText(r.subject,500),body:apiText(r.body,60000),recipients:apiText(r.recipients,3000),warnings:Array.isArray(r.warnings)?r.warnings.filter(n=>typeof n==='string').slice(0,60).map(n=>n.slice(0,500)):[],stale:r.stale===true,cnBody:apiText(r.cnBody,60000)};}if(JSON.stringify(out).length>210000)throw new Error('large');return out;}
function apiCanClose(p){const r=p.report,filled=k=>typeof r[k]==='string'&&r[k].trim()&&!/待补充|待调查|待验证|待确认|待指定|未验证|未完成/.test(r[k]);return r.reportStatus==='closed'&&apiValidSample(r)&&['rootCause','escapeCause','containment','containmentOwner','containmentDue','corrective','correctiveOwner','correctiveDue','preventive','preventiveOwner','preventiveDue','completion','validationPlan','validationResult','validator','validationDate','reviewer','reviewDate','author'].every(filled)&&r.validationOutcome==='pass'&&r.reviewDecision==='approved'&&p.checks.finalClosure===true;}
function apiSettings(x){const terms=(Array.isArray(x.terms)?x.terms:[]).slice(0,100).map(t=>({zh:apiText(t.zh,100).trim(),ja:apiText(t.ja,200).trim(),approved:t.approved===true})).filter(t=>t.zh&&t.ja);return {terms,reference:apiText(x.reference,12000)};}
