async function key(env){return crypto.subtle.importKey('raw',enc.encode(env.SESSION_KEY+':'+env.LOGIN_HASH),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
async function session(env){const now=Math.floor(Date.now()/1000),p=b64(enc.encode(JSON.stringify({iat:now,exp:now+TTL,nonce:crypto.randomUUID()})));return p+'.'+b64(await crypto.subtle.sign('HMAC',await key(env),enc.encode(p)));}
